                "\n" +
                "[policy_definition]\n" +
                "p = sub, obj, act\n" +
                "\n" +
                "[policy_effect]\n" +
                "e = some(where (p.eft == allow))\n" +
                "\n" +
                "[matchers]\n" +
                "m = r.sub == p.sub && r.obj == p.obj && r.act == p.act");
    }

    @Test
    void testValidPolicyLine() {
        String line = "p, alice, data1, read";
        Helper.loadPolicyLine(line, model);

        List<List<String>> policies = model.model.get("p").get("p").policy;
        assertEquals(1, policies.size());
        assertEquals(4, policies.get(0).size());
        assertEquals("p", policies.get(0).get(0));
        assertEquals("alice", policies.get(0).get(1));
        assertEquals("data1", policies.get(0).get(2));
        assertEquals("read", policies.get(0).get(3));
    }

