    void testCommentLine() {
        String line = "# This is a comment";
        assertDoesNotThrow(() -> Helper.loadPolicyLine(line, model));

        List<List<String>> policies = model.model.get("p").get("p").policy;
        assertTrue(policies.isEmpty());
    }

