class RemoveMatchesTests {

    private Role roleA;
    private Role roleB;
    private Role roleC;

    @BeforeEach
    void setUp() {
        roleA = new Role("roleA");
        roleB = new Role("roleB");
        roleC = new Role("roleC");
    }

    @Test
    void testRemoveMatchesWithEmptyMatchedBy() {
        // Given: A role with empty matchedBy map
        assertTrue(roleA.matchedBy.isEmpty());

        // When: removeMatches is called
        roleA.removeMatches();

        // Then: matchedBy remains empty and matched map is also empty
        assertTrue(roleA.matchedBy.isEmpty());
        assertTrue(roleA.matched.isEmpty());
    }

    @Test
    void testRemoveMatchesWithSingleMatch() {
        // Given: Setup matching relationships
        roleA.matchedBy.put("roleB", roleB);
        roleB.matched.put("roleA", roleA);

        // When: removeMatches is called on roleA
        roleA.removeMatches();

        // Then: roleA's matchedBy is cleared and roleB's matched no longer contains roleA
        assertTrue(roleA.matchedBy.isEmpty());
        assertFalse(roleB.matched.containsKey("roleA"));
    }

    @Test
    void testRemoveMatchesWithMultipleMatches() {
        // Given: Setup multiple matching relationships
        roleA.matchedBy.put("roleB", roleB);
        roleA.matchedBy.put("roleC", roleC);
        roleB.matched.put("roleA", roleA);
        roleC.matched.put("roleA", roleA);

        // When: removeMatches is called on roleA
        roleA.removeMatches();

        // Then: roleA's matchedBy is cleared and other roles' matched maps no longer contain roleA
        assertTrue(roleA.matchedBy.isEmpty());
        assertFalse(roleB.matched.containsKey("roleA"));
        assertFalse(roleC.matched.containsKey("roleA"));
    }

    @Test
    void testRemoveMatchesWhenMatchedMapDoesNotExist() {
        // Given: Setup matching relationship where matchedBy has entry but matched map is missing
        roleA.matchedBy.put("roleB", roleB);
        // Intentionally not adding to roleB.matched

        // When: removeMatches is called on roleA
        roleA.removeMatches();

        // Then: roleA's matchedBy is cleared without throwing exception
        assertTrue(roleA.matchedBy.isEmpty());
    }

    @Test
    void testRemoveMatchesBidirectionalRelationships() {
        // Given: Setup bidirectional matching relationships
        roleA.matchedBy.put("roleB", roleB);
        roleB.matchedBy.put("roleA", roleA);
        roleA.matched.put("roleB", roleB);
        roleB.matched.put("roleA", roleA);

        // When: removeMatches is called on roleA
        roleA.removeMatches();

        // Then: roleA's matchedBy is cleared, roleA is removed from roleB's matched,
        // but roleB's matchedBy still contains roleA (since we only called removeMatches on roleA)
        assertTrue(roleA.matchedBy.isEmpty());
        assertFalse(roleB.matched.containsKey("roleA"));
        assertTrue(roleB.matchedBy.containsKey("roleA"));
    }

    @Test
    void testRemoveMatchesIdempotent() {
        // Given: Setup matching relationships
        roleA.matchedBy.put("roleB", roleB);
        roleB.matched.put("roleA", roleA);

        // When: removeMatches is called twice
        roleA.removeMatches();
        roleA.removeMatches();

        // Then: No exception is thrown and state remains consistent
        assertTrue(roleA.matchedBy.isEmpty());
        assertFalse(roleB.matched.containsKey("roleA"));
    }
